<?php require_once '../config/database.php';require_once '../config/auth.php';if(logged_in())go_role();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama']??'');$email=trim($_POST['email']??'');$hp=trim($_POST['no_hp']??'');$alamat=trim($_POST['alamat']??'');$tgl=$_POST['tanggal_lahir']??'';$username=trim($_POST['username']??'');$password=$_POST['password']??'';try{if(strlen($password)<6)throw new RuntimeException('Password minimal 6 karakter.');$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users(username,password,role) VALUES(?,?,'pelamar')");$q->execute([$username,hash('sha256',$password)]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO pelamar(id_user,nama,email,no_hp,alamat,tanggal_lahir) VALUES(?,?,?,?,?,?)');$q->execute([$uid,$nama,$email,$hp,$alamat,$tgl]);$pdo->commit();flash('Pendaftaran berhasil. Silakan login.');header('Location: ../auth/login.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e instanceof RuntimeException?$e->getMessage():'Pendaftaran gagal. Username atau email mungkin sudah digunakan.';}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftar Pelamar</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="login card"><h1>Daftar Pelamar</h1><?php if($err):?><p class="error"><?=e($err)?></p><?php endif;?><form method="post"><label>Nama<input name="nama" required></label><label>Email<input type="email" name="email" required></label><label>No. HP<input name="no_hp" required></label><label>Alamat<textarea name="alamat" required></textarea></label><label>Tanggal Lahir<input type="date" name="tanggal_lahir" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="btn">Daftar</button></form><p><a href="../auth/login.php">Kembali ke login</a></p></div></body></html>
